   169→          const token = tokens.find((t) => t.id === tokenId);
   170→          if (token) {
   171→            ws.publish(
   172→              `adventure:${adventureId}`,
   173→              serializeMessage({ type: "token:added", token })
   174→            );
   175→          }
   176→        }
   177→      }
   178→    },
   179→
   180→    async message(ws: ServerWebSocket<WsData>, raw: string | Buffer) {
   181→      const conn = getConnection(ws);
   182→      if (!conn) return;
   183→
   184→      const msg = parseMessage(typeof raw === "string" ? raw : raw.toString());
   185→      if (!msg) {
   186→        ws.send(serializeMessage({ type: "error", message: "Invalid message format" }));
   187→        return;
   188→      }
   189→
   190→      const { adventureId } = conn;
   191→      const topic = `adventure:${adventureId}`;
   192→
   193→      switch (msg.type) {
   194→        case "join": {
   195→          ws.send(serializeMessage({ type: "error", message: "Already joined" }));
   196→          break;
   197→        }
   198→
   199→        case "fog:stroke": {
   200→          if (conn.role !== "gm") {
   201→            ws.send(serializeMessage({ type: "error", message: "Only GM can send fog strokes" }));
   202→            break;
   203→          }
   204→          const adv = getAdventure(db, adventureId);
   205→          if (!adv?.active_image_id) {
   206→            ws.send(serializeMessage({ type: "error", message: "No active image" }));
   207→            break;
   208→          }
   209→          const imageId = adv.active_image_id;
   210→          const mask = await getFogMaskForImage(db, imageId, uploadsDir);
