   212→          scheduleSave(db, imageId);
   213→          ws.publish(topic, serializeMessage({ type: "fog:stroke", stroke: msg.stroke, imageId }));
   214→          break;
   215→        }
   216→
   217→        case "fog:stroke:batch": {
   218→          if (conn.role !== "gm") {
   219→            ws.send(serializeMessage({ type: "error", message: "Only GM can send fog strokes" }));
   220→            break;
   221→          }
   222→          const adv = getAdventure(db, adventureId);
   223→          if (!adv?.active_image_id) {
   224→            ws.send(serializeMessage({ type: "error", message: "No active image" }));
   225→            break;
   226→          }
   227→          const imageId = adv.active_image_id;
   228→          const mask = await getFogMaskForImage(db, imageId, uploadsDir);
   229→          applyStrokes(mask, msg.strokes);
   230→          scheduleSave(db, imageId);
   231→          ws.publish(topic, serializeMessage({ type: "fog:stroke:batch", strokes: msg.strokes, imageId }));
   232→          break;
   233→        }
   234→
   235→        case "token:move": {
   236→          if (!conn.tokenId || conn.tokenId !== msg.tokenId) {
   237→            ws.send(serializeMessage({ type: "error", message: "You do not own this token" }));
   238→            break;
   239→          }
   240→          updateTokenPosition(db, msg.tokenId, msg.x, msg.y);
   241→          const moved = serializeMessage({
   242→            type: "token:moved",
   243→            tokenId: msg.tokenId,
   244→            x: msg.x,
   245→            y: msg.y,
   246→          });
   247→          ws.send(moved);
   248→          ws.publish(topic, moved);
   249→          break;
   250→        }
   251→
   252→        case "map:switch": {
   253→          if (conn.role !== "gm") {
   254→            ws.send(serializeMessage({ type: "error", message: "Only GM can switch maps" }));
   255→            break;
   256→          }
   257→          try {
   258→            setActiveImage(db, adventureId, msg.imageId);
   259→          } catch {
   260→            ws.send(serializeMessage({ type: "error", message: "Invalid image" }));
   261→            break;
   262→          }
   263→          let fogMask: string | null = null;
   264→          try {
   265→            const mask = await getFogMaskForImage(db, msg.imageId, uploadsDir);
   266→            fogMask = await maskToBase64(mask);
   267→          } catch {
   268→            fogMask = null;
   269→          }
   270→          const switched = serializeMessage({
   271→            type: "map:switched",
   272→            imageId: msg.imageId,
   273→            fogMask,
   274→          });
   275→          ws.send(switched);
   276→          ws.publish(topic, switched);
   277→          break;
   278→        }
   279→
   280→        case "ping": {
   281→          ws.send(serializeMessage({ type: "pong" }));
   282→          break;
   283→        }
   284→
   285→        default: {
   286→          ws.send(serializeMessage({ type: "error", message: "Unknown message type" }));
   287→        }
   288→      }
   289→    },
   290→
   291→    close(ws: ServerWebSocket<WsData>) {
   292→      const info = unregisterConnection(ws);
   293→      if (!info) return;
   294→
   295→      if (info.role === "gm") {
