   302→        }
   303→      }
   304→
   305→      const topic = `adventure:${info.adventureId}`;
   306→
   307→      if (info.role === "player" && info.tokenId) {
   308→        deleteToken(db, info.tokenId);
   309→        ws.publish(topic, serializeMessage({ type: "token:removed", tokenId: info.tokenId }));
   310→      }
   311→
   312→      if (info.playerName) {
   313→        ws.publish(topic, serializeMessage({ type: "player:left", playerName: info.playerName }));
   314→      }
   315→    },
   316→  };
