    11→const password = fragment.get('password') ?? '';
    12→
    13→if (!adventureId || !password) {
    14→  document.body.innerHTML = '<p style="padding:2rem">Missing adventure ID or password. <a href="/">Return home</a></p>';
    15→  throw new Error('Missing params');
    16→}
    17→
    18→// --- State ---
    19→let brushRadius = 50;
    20→let brushMode: 'reveal' | 'fog' = 'reveal';
    21→let activeImageId: string | null = null;
    22→let imageList: api.ImageRecord[] = [];
    23→
    24→// --- DOM ---
    25→const adventureNameEl = document.getElementById('adventure-name')!;
    26→const inviteLinkEl = document.getElementById('invite-link')!;
    27→const copyInviteBtn = document.getElementById('copy-invite')!;
    28→const brushSizeSlider = document.getElementById('brush-size') as HTMLInputElement;
    29→const brushSizeLabel = document.getElementById('brush-size-label')!;
    30→const modeRevealBtn = document.getElementById('mode-reveal')!;
    31→const modeFogBtn = document.getElementById('mode-fog')!;
    32→const gallery = document.getElementById('gallery')!;
    33→const uploadInput = document.getElementById('upload-input') as HTMLInputElement;
    34→const statusBar = document.getElementById('status-bar')!;
    35→const canvasArea = document.getElementById('canvas-area')!;
    36→
    37→// --- Canvas ---
    38→const canvasCtrl = initCanvas(canvasArea);
    39→
    40→// --- Viewport ---
    41→const viewport = createViewport();
    42→viewport.attach(canvasArea, canvasCtrl.getWrapper(), () => canvasCtrl.getImageSize());
    43→
    44→// --- Token layer (non-interactive for GM) ---
    45→const tokenCtrl = initTokenLayer(
    46→  canvasCtrl.getWrapper(),
    47→  () => canvasCtrl.getImageSize(),
    48→  (x, y) => viewport.screenToImage(x, y),
    49→  { interactive: false }
    50→);
    51→
    52→// --- WebSocket ---
    53→const ws = connectGM(adventureId, password);
    54→
    55→ws.on('connect', () => { statusBar.textContent = ''; });
    56→ws.on('disconnect', () => { statusBar.textContent = 'Reconnecting\u2026'; });
    57→ws.on('error', (msg) => { console.error('WS error', msg); });
    58→
    59→ws.on('joined', async (msg) => {
    60→  const adv = msg.adventure as { id: string; name: string; activeImageId: string | null };
    61→  adventureNameEl.textContent = adv.name;
    62→
    63→  try {
    64→    const advData = await api.getAdventure(adventureId, password);
    65→    const inviteUrl = `${location.origin}/player#link=${encodeURIComponent(advData.player_link)}`;
    66→    inviteLinkEl.textContent = inviteUrl;
    67→    copyInviteBtn.onclick = () => {
    68→      navigator.clipboard.writeText(inviteUrl).catch(() => {});
    69→    };
    70→  } catch {}
    71→
    72→  activeImageId = adv.activeImageId;
    73→  imageList = await api.listImages(adventureId, password);
    74→  renderGallery();
    75→
    76→  if (activeImageId) {
    77→    const img = imageList.find(i => i.id === activeImageId);
    78→    if (img) {
    79→      await canvasCtrl.loadImage(`/uploads/${img.filename}`);
    80→      viewport.resetView();
    81→      if (typeof msg.fogMask === 'string') {
    82→        await canvasCtrl.applyFogMask(msg.fogMask);
    83→      }
    84→    }
    85→  }
    86→
    87→  const tokens = msg.tokens as Array<{ id: string; name: string; color: string; x: number; y: number }>;
    88→  for (const token of tokens) {
    89→    tokenCtrl.addToken(token);
    90→  }
    91→});
    92→
    93→ws.on('fog:stroke', (msg) => {
    94→  if (msg.imageId === activeImageId) {
    95→    canvasCtrl.applyStroke(msg.stroke as FogStroke);
    96→  }
    97→});
    98→
    99→ws.on('fog:stroke:batch', (msg) => {
   100→  if (msg.imageId === activeImageId) {
   101→    for (const stroke of msg.strokes as FogStroke[]) {
   102→      canvasCtrl.applyStroke(stroke);
   103→    }
   104→  }
   105→});
   106→
   107→ws.on('token:added', (msg) => {
   108→  const token = msg.token as { id: string; name: string; color: string; x: number; y: number };
   109→  tokenCtrl.addToken(token);
   110→});
   111→
   112→ws.on('token:moved', (msg) => {
   113→  tokenCtrl.moveToken(msg.tokenId as string, msg.x as number, msg.y as number);
   114→});
   115→
   116→ws.on('token:removed', (msg) => {
   117→  tokenCtrl.removeToken(msg.tokenId as string);
   118→});
   119→
   120→ws.on('map:switched', async (msg) => {
   121→  activeImageId = msg.imageId as string;
   122→  imageList = await api.listImages(adventureId, password);
   123→  const img = imageList.find(i => i.id === activeImageId);
   124→  if (img) {
   125→    await canvasCtrl.loadImage(`/uploads/${img.filename}`);
   126→    viewport.resetView();
   127→    if (typeof msg.fogMask === 'string') {
   128→      await canvasCtrl.applyFogMask(msg.fogMask);
   129→    }
   130→  }
   131→  renderGallery();
   132→  tokenCtrl.render();
   133→});
   134→
   135→// --- Gallery ---
   136→function renderGallery() {
   137→  gallery.innerHTML = '';
   138→  for (const img of imageList) {
   139→    const item = document.createElement('div');
   140→    item.className = 'gallery-item' + (img.id === activeImageId ? ' active' : '');
   141→
   142→    const thumb = document.createElement('img');
   143→    thumb.src = `/uploads/${img.filename}`;
   144→    thumb.alt = img.original_name;
   145→    thumb.title = img.original_name;
   146→    item.appendChild(thumb);
   147→
   148→    item.addEventListener('click', () => {
   149→      ws.send({ type: 'map:switch', imageId: img.id });
   150→    });
   151→    gallery.appendChild(item);
   152→  }
   153→}
   154→
   155→// --- Upload ---
   156→uploadInput.addEventListener('change', async () => {
   157→  const file = uploadInput.files?.[0];
   158→  if (!file) return;
   159→  try {
   160→    await api.uploadImage(adventureId, password, file);
   161→    imageList = await api.listImages(adventureId, password);
   162→    renderGallery();
   163→  } catch (e) {
   164→    console.error('Upload failed', e);
   165→  }
   166→  uploadInput.value = '';
   167→});
   168→
   169→// --- Brush controls ---
   170→brushSizeSlider.addEventListener('input', () => {
   171→  brushRadius = parseInt(brushSizeSlider.value, 10);
   172→  brushSizeLabel.textContent = `${brushRadius}px`;
   173→});
   174→
