     2→import { startWsTestServer, type WsTestServer } from "../helpers";
     3→import { createAdventure } from "../../src/db/adventures";
     4→import { createImageRecord } from "../../src/db/images";
     5→import { getTokensByAdventure } from "../../src/db/tokens";
     6→import { flushAllFogCaches } from "../../src/ws/handler";
     7→import { loadFogMask } from "../../src/fog/serialize";
     8→
     9→// ---- WebSocket test helpers ----
    10→
    11→function connectWS(wsUrl: string, params: Record<string, string>): Promise<WebSocket> {
    12→  const url = new URL(`${wsUrl}/ws`);
    13→  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
    14→  return new Promise((resolve, reject) => {
    15→    const ws = new WebSocket(url.toString());
    16→    const timer = setTimeout(() => {
    17→      ws.close();
    18→      reject(new Error("WebSocket connect timeout"));
    19→    }, 5000);
    20→    ws.onopen = () => {
    21→      clearTimeout(timer);
    22→      resolve(ws);
    23→    };
    24→    ws.onerror = () => {
    25→      clearTimeout(timer);
    26→      reject(new Error("WebSocket connection error"));
    27→    };
    28→  });
    29→}
    30→
    31→function waitForMessage(ws: WebSocket, type: string, timeout = 3000): Promise<any> {
    32→  return new Promise((resolve, reject) => {
    33→    const timer = setTimeout(() => {
    34→      ws.removeEventListener("message", handler);
    35→      reject(new Error(`Timeout waiting for message type: ${type}`));
    36→    }, timeout);
    37→    const handler = (event: MessageEvent) => {
    38→      const msg = JSON.parse(event.data as string);
    39→      if (msg.type === type) {
    40→        clearTimeout(timer);
    41→        ws.removeEventListener("message", handler);
    42→        resolve(msg);
    43→      }
    44→    };
    45→    ws.addEventListener("message", handler);
    46→  });
    47→}
    48→
    49→function closeWs(ws: WebSocket): Promise<void> {
    50→  return new Promise((resolve) => {
    51→    if (ws.readyState === WebSocket.CLOSED) {
    52→      resolve();
    53→      return;
    54→    }
